class TransactionRow extends DataClass implements Insertable<TransactionRow> {
  /// معرّف UUID يُولَّد محليًا.
  final String id;
  final DateTime createdAt;
  final DateTime updatedAt;

  /// حذف ناعم: null يعني السجل فعّال.
  final DateTime? deletedAt;
  final String syncStatus;

  /// معرّف السجل على الخادم (يُملأ بعد أول مزامنة ناجحة).
  final String? remoteId;
  final TransactionType type;

  /// تاريخ العملية (قد يختلف عن وقت إنشاء السجل).
  final DateTime date;

  /// الحساب الذي تمت عليه العملية (المصدر في التحويل).
  final String accountId;

  /// الحساب الوجهة (للتحويل فقط).
  final String? toAccountId;
  final String? contactId;
  final String? categoryId;

  /// إجمالي العملية بأصغر وحدة نقدية.
  final int total;

  /// المبلغ المدفوع فعليًا بأصغر وحدة نقدية.
  final int paidAmount;
  final String? note;
  const TransactionRow({
    required this.id,
    required this.createdAt,
    required this.updatedAt,
    this.deletedAt,
    required this.syncStatus,
    this.remoteId,
    required this.type,
    required this.date,
    required this.accountId,
    this.toAccountId,
    this.contactId,
    this.categoryId,
    required this.total,
    required this.paidAmount,
    this.note,
  });
